import {BASE_RULES,validateRules,evaluateStrategy,selectHistory} from './strategy.mjs';
import {money,clamp} from './engine.mjs';

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const px=n=>(n/100).toLocaleString('en-US',{maximumFractionDigits:2})+'¢';
const sign=n=>(n<0?'−':'+')+money(Math.abs(n));
const time=t=>new Date(t).toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false,timeZone:'America/New_York'});
const storeKey='ds-market-lab:strategies:v1';
const newID=()=>crypto.randomUUID();

export function createStrategyLab(host){
 let saved=[],draft={...BASE_RULES},selected='draft',range='100rounds',mode='btc',wallet='A',trial=null,comparison=null,eventID=null,lastFingerprint='',saveOK=true;
 try{const s=JSON.parse(localStorage.getItem(storeKey)||'[]');if(Array.isArray(s))saved=s.filter(v=>{try{validateRules(v.rules);return typeof v.id==='string'&&Number.isInteger(v.number)&&typeof v.created==='string';}catch{return false;}});}catch{saveOK=false;}
 function frames(){const session=host.session();return selectHistory(session.frames.slice(0,session.cursor+1),range);}
 function rules(){return selected==='draft'?draft:saved.find(s=>s.id===selected)?.rules||draft;}
 function invalidate(){trial=null;comparison=null;lastFingerprint='';eventID=null;}
 function fingerprint(){const s=host.session();return JSON.stringify([s.id,s.cursor,range,selected,rules()]);}
 function runTest(){try{const f=frames();if(!f.length)throw new Error('No reached recording frames to test.');trial=evaluateStrategy(f,rules());lastFingerprint=fingerprint();eventID=trial.events.filter(e=>e.wallet===wallet).at(-1)?.id||null;host.refresh();host.notify('Practice rules evaluated on the reached recording only.');}catch(e){host.notify(e.message);}}
 function current(){return trial&&lastFingerprint===fingerprint()?trial:null;}
 function persist(){try{localStorage.setItem(storeKey,JSON.stringify(saved));saveOK=true;}catch{saveOK=false;host.notify('Strategy save failed. Export your versions before leaving this page.');}}
 function exportJSON(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function formValue(form,name){return Number(form.elements.namedItem(name).value);}
 function readDraft(){const f=document.querySelector('#strategy-form');if(!f||!f.reportValidity())return null;return validateRules({name:f.elements.namedItem('name').value,entry:f.elements.namedItem('entry').value,lookback:formValue(f,'lookback'),minMove:formValue(f,'minMove'),maxPrice:Math.round(formValue(f,'maxPrice')*100),takeProfit:Math.round(formValue(f,'takeProfit')*100),stopLoss:Math.round(formValue(f,'stopLoss')*100),aAmount:Math.round(formValue(f,'aAmount')*100),bFraction:formValue(f,'bFraction')/100,waitSeconds:120,exitSeconds:30});}
 function field(label,name,value,min,max,step=1,suffix=''){return `<label>${label}<div class="lab-input"><input required name="${name}" type="number" value="${value}" min="${min}" max="${max}" step="${step}" ${selected!=='draft'?'disabled':''}>${suffix?`<span>${suffix}</span>`:''}</div></label>`;}
 function chart(){const f=frames(),r=current();if(!f.length)return '<div class="empty-state">No recorded frames.</div>';const W=window.innerWidth<=600?600:1000,H=260,L=68,R=25,T=20,B=34;
  const value=(item,i)=>mode==='btc'?item.btc:mode==='contract'?(item.yesBid+item.yesAsk)/200:r?r.snapshots[i][wallet==='A'?0:1].equity/100:50;
  const values=f.map(value),min=Math.min(...values),max=Math.max(...values),pad=Math.max((max-min)*.14,mode==='btc'?10:mode==='contract'?5:1),lo=min-pad,hi=max+pad;
  const x=i=>L+i/Math.max(1,f.length-1)*(W-L-R),y=v=>T+(hi-v)/(hi-lo)*(H-T-B);
  let path='';f.forEach((item,i)=>{const next=mode==='contract'&&i&&f[i-1].market!==item.market;path+=`${i&&!next?'L':'M'}${x(i).toFixed(2)} ${y(values[i]).toFixed(2)} `;});
  const ticks=Array.from({length:5},(_,i)=>{const v=lo+(hi-lo)*i/4,yp=y(v);return `<line x1="${L}" x2="${W-R}" y1="${yp}" y2="${yp}" stroke="#26374b"/><text x="${L-8}" y="${yp+4}" text-anchor="end">${mode==='contract'?v.toFixed(0)+'¢':money(Math.round(v*100))}</text>`;}).join('');
  const markers=r?r.events.filter(e=>e.wallet===wallet).map(e=>{const f0=f[e.index];let v=mode==='btc'?f0.btc:mode==='contract'?(e.side==='YES'?e.price:10000-e.price)/100:value(f0,e.index);return `<g data-lab-event="${e.id}" tabindex="0" role="button" aria-label="Inspect ${e.type} ${e.side} at ${px(e.price)}"><title>${e.type} ${e.side} ${px(e.price)} · ${time(e.time)}</title><circle cx="${x(e.index)}" cy="${y(v)}" r="6" fill="${e.type==='BUY'?'#42d8a0':e.type==='SELL'?'#f6bd64':'#bc9cff'}" stroke="#0e1722" stroke-width="2"/><text x="${clamp(x(e.index),L+30,W-R-30)}" y="${clamp(y(v)+(e.type==='BUY'?21:-14),T+10,H-B-8)}" text-anchor="middle" class="lab-marker">${e.type==='BUY'?'BUY':e.type==='SELL'?'SELL':'END'}</text></g>`;}).join(''):'';
  return `<svg class="lab-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${mode==='btc'?'Fictional Bitcoin price':mode==='contract'?'YES contract midpoint, with gaps between rounds':'Estimated test equity'} history"><defs><linearGradient id="lab-gradient" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#3599de" stop-opacity=".16"/><stop offset="1" stop-color="#3599de" stop-opacity="0"/></linearGradient></defs>${ticks}<path d="${path} L${x(f.length-1)} ${H-B} L${L} ${H-B} Z" fill="${mode==='contract'?'none':'url(#lab-gradient)'}"/><path d="${path}" fill="none" stroke="#4bb5ff" stroke-width="2.2" stroke-linejoin="round"/><g data-lab-result>${markers}</g><text x="${L}" y="${H-9}">${time(f[0].time)} ET</text><text x="${W-R}" y="${H-9}" text-anchor="end">${time(f.at(-1).time)} ET</text></svg>`;
 }
 function eventDetail(){const r=current(),e=r?.events.find(e=>e.id===eventID);if(!e)return `<div class="empty-trade">Run a test, then select a BUY or SELL marker to inspect its decision.</div>`;const entry=r.events.filter(p=>p.wallet===e.wallet&&p.market===e.market&&p.type==='BUY'&&p.index<=e.index).at(-1);return `<div class="pillrow"><span class="pill">Agent ${e.wallet}</span><span class="event-type ${e.type.toLowerCase()}">${e.type}</span></div><dl class="lab-event-dl"><dt>Time ET</dt><dd>${time(e.time)}</dd><dt>Contract / fill</dt><dd>${e.side} ${px(e.price)}</dd><dt>${e.type==='BUY'?'Spent':'Received'}</dt><dd>${money(Math.abs(e.net))}</dd><dt>Modeled fee</dt><dd>${money(e.fee)}</dd>${e.pnl===undefined?'':`<dt>Realized on fill</dt><dd class="${e.pnl<0?'red':'green'}">${sign(e.pnl)}</dd>`}</dl>${e.type!=='BUY'&&entry?`<div class="reason-panel"><h3>Why it bought · ${px(entry.price)}</h3><p>${esc(entry.reason)}</p></div>`:''}<div class="reason-panel"><h3>${e.type==='BUY'?'Why it bought':e.type==='SELL'?'Why it sold':'Why it settled'}</h3><p>${esc(e.reason)}</p></div><button class="text-button" data-lab-action="replay">Replay this test ↗</button>`;}
 function compareTable(){if(!comparison||comparison.fingerprint!==fingerprint())return '<p class="empty-trade">Compare saved versions on the same reached data, after the same modeled costs.</p>';return `<div class="table-wrap"><table><thead><tr><th>Version</th><th>Agent</th><th>Net</th><th>Fees</th><th>Drawdown</th><th>Closed</th></tr></thead><tbody>${comparison.flatMap(c=>c.report.wallets.map(w=>`<tr><td>${esc(c.name)}</td><td>${w.id}</td><td class="${w.equity<5000?'red':'green'}">${sign(w.equity-5000)}</td><td>${money(w.fees)}</td><td>${money(w.maxDrawdown)}</td><td>${w.trades}</td></tr>`)).join('')}</tbody></table></div><p class="section-note">All versions start fresh at $50 per wallet. Net includes estimated open-position value. Repeated tuning on these fictional prices does not establish predictive skill.</p>`;}
 function render(){const f=frames(),r=current(),s=host.session(),cfg=rules(),count=new Set(f.map(f=>f.market)).size;
  return `<section class="panel"><div class="panel-title"><div><h2>Market history</h2><p>${esc(s.title)} · ${count} available round${count===1?'':'s'} · ${f.length} reached frames</p></div><select class="select" id="lab-range" aria-label="History range">${[['10rounds','Last 10 rounds'],['100rounds','Last 100 rounds'],['7days','7 days'],['30days','30 days'],['100days','100 days']].map(([v,l])=>`<option value="${v}" ${range===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="filter-row"><div class="lab-tabs">${[['btc','Bitcoin price'],['contract','Contract price'],['equity','Test bankroll']].map(([v,l])=>`<button data-lab-mode="${v}" class="${mode===v?'selected':''}">${l}</button>`).join('')}</div><label>Markers <select class="select" id="lab-wallet"><option value="A" ${wallet==='A'?'selected':''}>Agent A</option><option value="B" ${wallet==='B'?'selected':''}>Agent B</option></select></label></div><div class="lab-chart-scroll">${chart()}</div><div class="lab-chart-footer"><span>${s.source==='fictional-practice'?'FICTIONAL PRACTICE':'UNVERIFIED IMPORT'} · Available reached history only${mode==='contract'?' · Separate rounds are not connected':''}</span><button class="button small ghost" data-lab-action="full">Advance practice to end</button></div><p class="section-note">A 100-day selection does not create 100 days of data. The current fixture covers only 90 minutes. New trial results are separate from the original wallet history.</p></section><div class="lab-columns"><section class="panel"><div class="panel-title"><h2>Trade explanation</h2><span class="pill" data-lab-test-state>${r?'TEST RESULT':'NOT TESTED'}</span></div><div data-lab-result>${eventDetail()}</div></section><section class="panel"><div class="panel-title"><h2>Strategy builder</h2>${selected!=='draft'?'<button class="text-button" data-lab-action="duplicate">Copy to draft ↗</button>':''}</div><label class="lab-label">Version<select id="lab-version" class="select"><option value="draft">Unsaved draft</option>${saved.map(v=>`<option value="${esc(v.id)}" ${selected===v.id?'selected':''}>v${v.number} · ${esc(v.rules.name)}</option>`).join('')}</select></label><form id="strategy-form"><label>Name<input required name="name" value="${esc(cfg.name)}" maxlength="60" ${selected!=='draft'?'disabled':''}></label><label>Entry behavior<select name="entry" ${selected!=='draft'?'disabled':''}><option value="momentum" ${cfg.entry==='momentum'?'selected':''}>Follow momentum</option><option value="reversal" ${cfg.entry==='reversal'?'selected':''}>Test reversal</option></select></label><div class="lab-fields">${field('Look back','lookback',cfg.lookback,15,300,15,'sec')}${field('Minimum spot move','minMove',cfg.minMove,.01,10000,.01,'$')}${field('Buy at or below','maxPrice',cfg.maxPrice/100,1,99,.5,'¢')}${field('Profit exit','takeProfit',cfg.takeProfit/100,1,99,.5,'¢ gain')}${field('Loss exit','stopLoss',cfg.stopLoss/100,1,99,.5,'¢ loss')}${field('A: entry budget','aAmount',cfg.aAmount/100,1,10,.5,'$')}${field('B: available cash','bFraction',cfg.bFraction*100,1,100,1,'%')}</div><p class="section-note">One entry signal per round. Wait at least 2 minutes; stop new entries with 2 minutes left. Attempt to exit with 30 seconds left. A remains capped at $10; B never borrows.</p><div class="setup-cta"><button type="button" class="button" data-lab-action="test">Test these rules</button><button type="button" class="button secondary" data-lab-action="save" ${selected!=='draft'?'disabled':''}>Save version</button></div></form><p class="section-note">${saveOK?'Versions save on this browser. Existing versions cannot be edited.':'Browser saving unavailable. Export versions before leaving.'}</p></section><section class="panel"><div class="panel-title"><h2>Compare strategies</h2></div><div class="lab-version-list">${saved.length?saved.map(v=>`<div><strong>v${v.number} · ${esc(v.rules.name)}</strong><small>${esc(v.rules.entry)} · A $${(v.rules.aAmount/100).toFixed(2)} · B ${(v.rules.bFraction*100).toFixed(0)}%</small></div>`).join(''):'<p class="empty-trade">Save a strategy version to start your comparison library.</p>'}</div><div class="setup-cta"><button class="button secondary" data-lab-action="compare">Compare versions</button><button class="button ghost" data-lab-action="export">Export versions</button></div><div data-lab-result>${compareTable()}</div><div class="lab-future"><strong>Coming after connections</strong><p>AI-proposed rules, real recorded market history, forward paper tests, phone alerts, and the separate long-term investment watchlist.</p></div></section></div>`;
 }
 function click(e){const point=e.target.closest('[data-lab-event]');if(point){eventID=point.dataset.labEvent;host.refresh();return;}
  const m=e.target.closest('[data-lab-mode]');if(m){mode=m.dataset.labMode;host.refresh();return;}
  const a=e.target.closest('[data-lab-action]')?.dataset.labAction;if(!a)return;
  try{if(a==='test'){if(selected==='draft'){const next=readDraft();if(!next)return;draft=next;}runTest();}
   else if(a==='save'){const next=readDraft();if(!next)return;draft=next;const v={id:newID(),number:Math.max(0,...saved.map(v=>v.number))+1,created:new Date().toISOString(),rules:{...draft}};saved.push(v);selected=v.id;persist();invalidate();host.refresh();host.notify(saveOK?'Strategy version saved.':'Version is in memory only; export it.');}
   else if(a==='duplicate'){draft={...rules()};selected='draft';invalidate();host.refresh();}
   else if(a==='compare'){if(selected==='draft'){const next=readDraft();if(!next)return;draft=next;}const f=frames(),entries=[...(selected==='draft'?[{name:'Current draft',rules:rules()}]:[]),...saved.map(v=>({name:'v'+v.number+' '+v.rules.name,rules:v.rules}))];comparison=entries.map(v=>({...v,report:evaluateStrategy(f,v.rules)}));comparison.fingerprint=fingerprint();host.refresh();host.notify('Compared on the same reached frames, with fresh wallets for each version.');}
   else if(a==='full'){host.useAll();invalidate();host.refresh();}
   else if(a==='replay'){const r=current();if(r){const chosen=r.events.find(e=>e.id===eventID);host.openTest({frames:r.frames,rules:r.rules,eventIndex:chosen?.index||0,source:host.session().source,title:'Strategy test · '+r.rules.name});}}
   else if(a==='export')exportJSON({kind:'ds-market-lab-strategy-library',version:1,exported:new Date().toISOString(),saved,notice:'User-authored rules. Not trained AI or proven performance.'},'DS-Market-Lab-Strategies.json');
  }catch(error){host.notify(error.message);}
 }
 function change(e){if(e.target.closest('#strategy-form')&&selected==='draft'){invalidate();document.querySelectorAll('[data-lab-result]').forEach(el=>el.setAttribute('hidden',''));const status=document.querySelector('[data-lab-test-state]');if(status)status.textContent='DRAFT CHANGED · RETEST';try{const next=readDraft();if(next){draft=next;invalidate();document.querySelectorAll('[data-lab-result]').forEach(el=>el.setAttribute('hidden',''));const status=document.querySelector('[data-lab-test-state]');if(status)status.textContent='DRAFT CHANGED · RETEST';}}catch{}return;}if(e.target.id==='lab-range'){range=e.target.value;invalidate();host.refresh();}else if(e.target.id==='lab-wallet'){wallet=e.target.value;host.refresh();}else if(e.target.id==='lab-version'){selected=e.target.value;invalidate();host.refresh();}}
 return {render,click,change};
}
